[CreateRecognizer][google.cloud.speech.v2.Speech.CreateRecognizer] method.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->recognizer() >> / C<< $msg->recognizer($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::Recognizer>)

Required. The Recognizer to create.

=item * C<< $msg->validate_only() >> / C<< $msg->validate_only($value) >>

Type: C<Bool>

If set, validate the request and preview the Recognizer, but do not
actually create it.

=item * C<< $msg->recognizer_id() >> / C<< $msg->recognizer_id($value) >>

Type: C<String>

The ID to use for the Recognizer, which will become the final component of
the Recognizer's resource name.

This value should be 4-63 characters, and valid characters
are /[a-z][0-9]-/.

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The project and location where this Recognizer will be created.
The expected format is `projects/{project}/locations/{location}`.

=back

