=head2 Google::Cloud::Speech::V2::CloudSpeech::RecognitionFeatures

Available recognition features.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->profanity_filter() >> / C<< $msg->profanity_filter($value) >>

Type: C<Bool>

If set to `true`, the server will attempt to filter out profanities,
replacing all but the initial character in each filtered word with
asterisks, for instance, "f***". If set to `false` or omitted, profanities
won't be filtered out.

=item * C<< $msg->enable_word_time_offsets() >> / C<< $msg->enable_word_time_offsets($value) >>

Type: C<Bool>

If `true`, the top result includes a list of words and the start and end
time offsets (timestamps) for those words. If `false`, no word-level time
offset information is returned. The default is `false`.

=item * C<< $msg->enable_word_confidence() >> / C<< $msg->enable_word_confidence($value) >>

Type: C<Bool>

If `true`, the top result includes a list of words and the confidence for
those words. If `false`, no word-level confidence information is returned.
The default is `false`.

=item * C<< $msg->enable_automatic_punctuation() >> / C<< $msg->enable_automatic_punctuation($value) >>

Type: C<Bool>

If `true`, adds punctuation to recognition result hypotheses. This feature
is only available in select languages. The default `false` value does not
add punctuation to result hypotheses.

=item * C<< $msg->enable_spoken_punctuation() >> / C<< $msg->enable_spoken_punctuation($value) >>

Type: C<Bool>

The spoken punctuation behavior for the call. If `true`, replaces spoken
punctuation with the corresponding symbols in the request. For example,
"how are you question mark" becomes "how are you?". See
https://cloud.google.com/speech-to-text/docs/spoken-punctuation for
support. If `false`, spoken punctuation is not replaced.

=item * C<< $msg->enable_spoken_emojis() >> / C<< $msg->enable_spoken_emojis($value) >>

Type: C<Bool>

The spoken emoji behavior for the call. If `true`, adds spoken emoji
formatting for the request. This will replace spoken emojis with the
corresponding Unicode symbols in the final transcript. If `false`, spoken
emojis are not replaced.

=item * C<< $msg->multi_channel_mode() >> / C<< $msg->multi_channel_mode($value) >>

Type: C<Enum> (L<Google::Cloud::Speech::V2::RecognitionFeatures::MultiChannelMode>)

Mode for recognizing multi-channel audio.

=item * C<< $msg->diarization_config() >> / C<< $msg->diarization_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::SpeakerDiarizationConfig>)

Configuration to enable speaker diarization. To enable diarization, set
this field to an empty SpeakerDiarizationConfig message.

=item * C<< $msg->max_alternatives() >> / C<< $msg->max_alternatives($value) >>

Type: C<Int32>

Maximum number of recognition hypotheses to be returned.
The server may return fewer than `max_alternatives`.
Valid values are `0`-`30`. A value of `0` or `1` will return a maximum of
one. If omitted, will return a maximum of one.

=item * C<< $msg->custom_prompt_config() >> / C<< $msg->custom_prompt_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::CustomPromptConfig>)

Optional. Configuration to enable custom prompt for chirp3.

=back

=head3 Enum: RecognitionFeatures::MultiChannelMode

=over 4

=item * C<MULTI_CHANNEL_MODE_UNSPECIFIED> => C<0>

=item * C<SEPARATE_RECOGNITION_PER_CHANNEL> => C<1>

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::TranscriptNormalization

Transcription normalization configuration. Use transcription normalization
to automatically replace parts of the transcript with phrases of your
choosing. For StreamingRecognize, this normalization only applies to stable
partial transcripts (stability > 0.8) and final transcripts.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->entries() >> / C<< $msg->entries($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::TranscriptNormalization::Entry>)

A list of replacement entries. We will perform replacement with one entry
at a time. For example, the second entry in ["cat" => "dog", "mountain cat"
 => "mountain dog"] will never be applied because we will always process the
first entry before it. At most 100 entries.

=back

