Translation configuration. Use to translate the given audio into text for the
desired language.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->target_language() >> / C<< $msg->target_language($value) >>

Type: C<String>

Required. The language code to translate to.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::SpeechAdaptation

Provides "hints" to the speech recognizer to favor specific words and phrases
in the results. PhraseSets can be specified as an inline resource, or a
reference to an existing PhraseSet resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->phrase_sets() >> / C<< $msg->phrase_sets($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::SpeechAdaptation::AdaptationPhraseSet>)

A list of inline or referenced PhraseSets.

=item * C<< $msg->custom_classes() >> / C<< $msg->custom_classes($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::CustomClass>)

A list of inline CustomClasses. Existing CustomClass resources can be
referenced directly in a PhraseSet.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::DenoiserConfig

Denoiser config. May not be supported for all models and may
have no effect.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->denoise_audio() >> / C<< $msg->denoise_audio($value) >>

Type: C<Bool>

Denoise audio before sending to the transcription model.

=item * C<< $msg->snr_threshold() >> / C<< $msg->snr_threshold($value) >>

Type: C<Float>

Signal-to-Noise Ratio (SNR) threshold for the denoiser. Here SNR means the
loudness of the speech signal. Audio with an SNR below this threshold,
meaning the speech is too quiet, will be prevented from being sent to the
transcription model.

If snr_threshold=0, no filtering will be applied.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::RecognitionConfig

Provides information to the Recognizer that specifies how to process the
recognition request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->auto_decoding_config() >> / C<< $msg->auto_decoding_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::AutoDetectDecodingConfig>)

Automatically detect decoding parameters.
Preferred for supported formats.

=item * C<< $msg->explicit_decoding_config() >> / C<< $msg->explicit_decoding_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::ExplicitDecodingConfig>)

Explicitly specified decoding parameters.
Required if using headerless PCM audio (linear16, mulaw, alaw).

=item * C<< $msg->model() >> / C<< $msg->model($value) >>

Type: C<String>

Optional. Which model to use for recognition requests. Select the model
best suited to your domain to get best results.

Guidance for choosing which model to use can be found in the [Transcription
Models
Documentation](https://cloud.google.com/speech-to-text/v2/docs/transcription-model)
and the models supported in each region can be found in the [Table Of
Supported
Models](https://cloud.google.com/speech-to-text/v2/docs/speech-to-text-supported-languages).

=item * C<< $msg->language_codes() >> / C<< $msg->language_codes($value) >>

Type: C<String>

Optional. The language of the supplied audio as a
[BCP-47](https://www.rfc-editor.org/rfc/bcp/bcp47.txt) language tag.
Language tags are normalized to BCP-47 before they are used eg "en-us"
becomes "en-US".

Supported languages for each model are listed in the [Table of Supported
Models](https://cloud.google.com/speech-to-text/v2/docs/speech-to-text-supported-languages).

If additional languages are provided, recognition result will contain
recognition in the most likely language detected. The recognition result
will include the language tag of the language detected in the audio.

=item * C<< $msg->features() >> / C<< $msg->features($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::RecognitionFeatures>)

Speech recognition features to enable.

=item * C<< $msg->adaptation() >> / C<< $msg->adaptation($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::SpeechAdaptation>)

Speech adaptation context that weights recognizer predictions for specific
words and phrases.

=item * C<< $msg->transcript_normalization() >> / C<< $msg->transcript_normalization($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::TranscriptNormalization>)

Optional. Use transcription normalization to automatically replace parts of
the transcript with phrases of your choosing. For StreamingRecognize, this
normalization only applies to stable partial transcripts (stability > 0.8)
and final transcripts.

=item * C<< $msg->translation_config() >> / C<< $msg->translation_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::TranslationConfig>)

Optional. Optional configuration used to automatically run translation on
the given audio to the desired language for supported models.

=item * C<< $msg->denoiser_config() >> / C<< $msg->denoiser_config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::DenoiserConfig>)

Optional. Optional denoiser config. May not be supported for all models
and may have no effect.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::RecognizeRequest

Request message for the
[Recognize][google.cloud.speech.v2.Speech.Recognize] method. Either
`content` or `uri` must be supplied. Supplying both or neither returns
[INVALID_ARGUMENT][google.rpc.Code.INVALID_ARGUMENT]. See [content
limits](https://cloud.google.com/speech-to-text/quotas#content).

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->recognizer() >> / C<< $msg->recognizer($value) >>

Type: C<String>

Required. The name of the Recognizer to use during recognition. The
expected format is
`projects/{project}/locations/{location}/recognizers/{recognizer}`. The
{recognizer} segment may be set to `_` to use an empty implicit Recognizer.

=item * C<< $msg->config() >> / C<< $msg->config($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::RecognitionConfig>)

Features and audio metadata to use for the Automatic Speech Recognition.
This field in combination with the
[config_mask][google.cloud.speech.v2.RecognizeRequest.config_mask] field
can be used to override parts of the
[default_recognition_config][google.cloud.speech.v2.Recognizer.default_recognition_config]
of the Recognizer resource.

=item * C<< $msg->config_mask() >> / C<< $msg->config_mask($value) >>

Type: C<Message> (L<Google::Protobuf::FieldMask::FieldMask>)

The list of fields in
[config][google.cloud.speech.v2.RecognizeRequest.config] that override the
values in the
[default_recognition_config][google.cloud.speech.v2.Recognizer.default_recognition_config]
of the recognizer during this recognition request. If no mask is provided,
all non-default valued fields in
[config][google.cloud.speech.v2.RecognizeRequest.config] override the
values in the recognizer for this recognition request. If a mask is
provided, only the fields listed in the mask override the config in the
recognizer for this recognition request. If a wildcard (`*`) is provided,
[config][google.cloud.speech.v2.RecognizeRequest.config] completely
overrides and replaces the config in the recognizer for this recognition
request.

=item * C<< $msg->content() >> / C<< $msg->content($value) >>

Type: C<Bytes>

The audio data bytes encoded as specified in
[RecognitionConfig][google.cloud.speech.v2.RecognitionConfig]. As
with all bytes fields, proto buffers use a pure binary representation,
whereas JSON representations use base64.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI that points to a file that contains audio data bytes as specified in
[RecognitionConfig][google.cloud.speech.v2.RecognitionConfig]. The file
must not be compressed (for example, gzip). Currently, only Google Cloud
Storage URIs are supported, which must be specified in the following
format: `gs://bucket_name/object_name` (other URI formats return
[INVALID_ARGUMENT][google.rpc.Code.INVALID_ARGUMENT]). For more
information, see [Request
URIs](https://cloud.google.com/storage/docs/reference-uris).

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::RecognitionResponseMetadata

Metadata about the recognition request and response.

Inherits from L<Protobuf::Message>.

