Type: C<String>

Global request identifier auto-generated by the API.

=item * C<< $msg->total_billed_duration() >> / C<< $msg->total_billed_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

When available, billed audio seconds for the corresponding request.

=item * C<< $msg->prompt() >> / C<< $msg->prompt($value) >>

Type: C<String>

Optional. Output only. Provides the prompt used for the recognition
request.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::SpeechRecognitionAlternative

Alternative hypotheses (a.k.a. n-best list).

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->transcript() >> / C<< $msg->transcript($value) >>

Type: C<String>

Transcript text representing the words that the user spoke.

=item * C<< $msg->confidence() >> / C<< $msg->confidence($value) >>

Type: C<Float>

The confidence estimate between 0.0 and 1.0. A higher number
indicates an estimated greater likelihood that the recognized words are
correct. This field is set only for the top alternative of a non-streaming
result or, of a streaming result where
[is_final][google.cloud.speech.v2.StreamingRecognitionResult.is_final] is
set to `true`. This field is not guaranteed to be accurate and users should
not rely on it to be always provided. The default of 0.0 is a sentinel
value indicating `confidence` was not set.

=item * C<< $msg->words() >> / C<< $msg->words($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::WordInfo>)

A list of word-specific information for each recognized word.
When the
[SpeakerDiarizationConfig][google.cloud.speech.v2.SpeakerDiarizationConfig]
is set, you will see all the words from the beginning of the audio.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::WordInfo

Word-specific information for recognized words.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->start_offset() >> / C<< $msg->start_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Time offset relative to the beginning of the audio,
and corresponding to the start of the spoken word.
This field is only set if
[enable_word_time_offsets][google.cloud.speech.v2.RecognitionFeatures.enable_word_time_offsets]
is `true` and only in the top hypothesis. This is an experimental feature
and the accuracy of the time offset can vary.

=item * C<< $msg->end_offset() >> / C<< $msg->end_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Time offset relative to the beginning of the audio,
and corresponding to the end of the spoken word.
This field is only set if
[enable_word_time_offsets][google.cloud.speech.v2.RecognitionFeatures.enable_word_time_offsets]
is `true` and only in the top hypothesis. This is an experimental feature
and the accuracy of the time offset can vary.

=item * C<< $msg->word() >> / C<< $msg->word($value) >>

Type: C<String>

The word corresponding to this set of information.

=item * C<< $msg->confidence() >> / C<< $msg->confidence($value) >>

Type: C<Float>

The confidence estimate between 0.0 and 1.0. A higher number
indicates an estimated greater likelihood that the recognized words are
correct. This field is set only for the top alternative of a non-streaming
result or, of a streaming result where
[is_final][google.cloud.speech.v2.StreamingRecognitionResult.is_final] is
set to `true`. This field is not guaranteed to be accurate and users should
not rely on it to be always provided. The default of 0.0 is a sentinel
value indicating `confidence` was not set.

=item * C<< $msg->speaker_label() >> / C<< $msg->speaker_label($value) >>

Type: C<String>

A distinct label is assigned for every speaker within the audio. This field
specifies which one of those speakers was detected to have spoken this
word. `speaker_label` is set if
[SpeakerDiarizationConfig][google.cloud.speech.v2.SpeakerDiarizationConfig]
is given and only in the top alternative.

=back

=head2 Google::Cloud::Speech::V2::CloudSpeech::SpeechRecognitionResult

A speech recognition result corresponding to a portion of the audio.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->alternatives() >> / C<< $msg->alternatives($value) >>

Type: C<Message> (L<Google::Cloud::Speech::V2::CloudSpeech::SpeechRecognitionAlternative>)

May contain one or more recognition hypotheses. These alternatives are
ordered in terms of accuracy, with the top (first) alternative being the
most probable, as ranked by the recognizer.

=item * C<< $msg->channel_tag() >> / C<< $msg->channel_tag($value) >>

Type: C<Int32>

For multi-channel audio, this is the channel number corresponding to the
recognized result for the audio from that channel.
For `audio_channel_count` = `N`, its output values can range from `1` to
`N`.

=item * C<< $msg->result_end_offset() >> / C<< $msg->result_end_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Time offset of the end of this result relative to the beginning of the
audio.

=item * C<< $msg->language_code() >> / C<< $msg->language_code($value) >>

Type: C<String>

Output only. The [BCP-47](https://www.rfc-editor.org/rfc/bcp/bcp47.txt)
language tag of the language in this result. This language code was
detected to have the most likelihood of being spoken in the audio.

=back

